import re

def parse_duration(s: str) -> int:
    matches = re.findall(r'(\d+)([dhms])', s)
    if not matches or ''.join(n + u for n, u in matches) != s.replace(' ', ''):
        raise ValueError(f"Invalid duration: {s!r}")
    factors = {'d': 86400, 'h': 3600, 'm': 60, 's': 1}
    return sum(int(n) * factors[u] for n, u in matches) // 60

assert parse_duration('2d 4h 30m') == 3150
assert parse_duration('90s') == 1
try:
    parse_duration('garbage')
    assert False
except ValueError:
    pass
